BEGIN ISOLATION LEVEL REPEATABLE READ READ ONLY;
SET LOCAL search_path TO pg_catalog;
SELECT json_build_object('kind','schema','name',nspname,'owner',pg_get_userbyid(nspowner),'acl',(SELECT array_agg(x::text ORDER BY x::text) FROM unnest(coalesce(nspacl,acldefault('n',nspowner))) x)) FROM pg_namespace WHERE nspname !~ '^pg_' AND nspname<>'information_schema';
SELECT json_build_object('kind','column','schema',n.nspname,'table',c.relname,'name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notNull',a.attnotnull,'generated',a.attgenerated,'identity',a.attidentity,'default',pg_get_expr(d.adbin,d.adrelid)) FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attnum>0 AND NOT a.attisdropped AND c.relkind IN ('r','p') AND n.nspname !~ '^pg_' AND n.nspname<>'information_schema';
SELECT json_build_object('kind','relation','schema',n.nspname,'name',c.relname,'type',c.relkind,'owner',pg_get_userbyid(c.relowner),'acl',(SELECT array_agg(x::text ORDER BY x::text) FROM unnest(coalesce(c.relacl,acldefault(CASE WHEN c.relkind='S' THEN 's' ELSE 'r' END::"char",c.relowner))) x),'rls',c.relrowsecurity,'forceRls',c.relforcerowsecurity,'options',c.reloptions) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.relkind IN ('r','p','v','m','S') AND n.nspname !~ '^pg_' AND n.nspname<>'information_schema';
SELECT json_build_object('kind','constraint','schema',n.nspname,'name',c.conname,'table',c.conrelid::regclass::text,'type',c.contype,'validated',c.convalidated,'def',pg_get_constraintdef(c.oid)) FROM pg_constraint c JOIN pg_namespace n ON n.oid=c.connamespace WHERE n.nspname !~ '^pg_' AND n.nspname<>'information_schema';
SELECT json_build_object('kind','index','schema',n.nspname,'name',c.relname,'def',pg_get_indexdef(c.oid),'valid',i.indisvalid,'ready',i.indisready) FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname !~ '^pg_' AND n.nspname<>'information_schema';
SELECT json_build_object('kind','trigger','schema',n.nspname,'name',t.tgname,'table',t.tgrelid::regclass::text,'enabled',t.tgenabled,'def',pg_get_triggerdef(t.oid)) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE NOT t.tgisinternal AND n.nspname !~ '^pg_' AND n.nspname<>'information_schema';
SELECT json_build_object('kind','function','schema',n.nspname,'name',p.proname,'identity',pg_get_function_identity_arguments(p.oid),'owner',pg_get_userbyid(p.proowner),'acl',(SELECT array_agg(x::text ORDER BY x::text) FROM unnest(coalesce(p.proacl,acldefault('f',p.proowner))) x),'def',pg_get_functiondef(p.oid)) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE p.prokind IN ('f','p') AND n.nspname !~ '^pg_' AND n.nspname<>'information_schema';
SELECT json_build_object('kind','view','schema',n.nspname,'name',c.relname,'def',pg_get_viewdef(c.oid)) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.relkind IN ('v','m') AND n.nspname !~ '^pg_' AND n.nspname<>'information_schema';
SELECT json_build_object('kind','policy','schema',schemaname,'table',tablename,'name',policyname,'roles',roles,'command',cmd,'permissive',permissive,'qual',qual,'withCheck',with_check) FROM pg_policies;
SELECT json_build_object('kind','eventTrigger','name',evtname,'event',evtevent,'enabled',evtenabled,'owner',pg_get_userbyid(evtowner),'function',evtfoid::regproc::text,'tags',evttags) FROM pg_event_trigger;
SELECT json_build_object('kind','defaultAcl','owner',pg_get_userbyid(d.defaclrole),'schema',n.nspname,'type',d.defaclobjtype,'acl',d.defaclacl::text) FROM pg_default_acl d LEFT JOIN pg_namespace n ON n.oid=d.defaclnamespace;
SELECT json_build_object('kind','flyway','rank',installed_rank,'version',version,'description',description,'type',type,'script',script,'checksum',checksum,'installedBy',installed_by,'installedOn',installed_on,'success',success) FROM public.flyway_schema_history ORDER BY installed_rank;
ROLLBACK;
